using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Xml;
using System.Security.Cryptography;
using UnityEngine;
using UnityEditor;
using Object=UnityEngine.Object;

// One reusable, fail-closed texture policy and incremental native bundle gate.
public static class RebirthVehicleDeliveryPipeline
{
 [Serializable] public class Vehicle {public string name,prefab,original,bundle;public int wheels,seats;}
 [Serializable] public class Policy {public int policyVersion,albedoNormalMax,surfaceMaskMax,crunchQuality;public string sourceProject,output,definitions,items;public Vehicle[] vehicles;}
 class Plan {public string path,role,imageHash;public int cap,sourceW,sourceH;public TextureImporterFormat format;}
 static string Hash(string p){using(var f=File.OpenRead(p))using(var s=SHA256.Create())return BitConverter.ToString(s.ComputeHash(f)).Replace("-","");}
 static string Role(string p){string k=p.ToLowerInvariant();if(k.Contains("normal")||k=="_bumpmap")return "normal";if(k.Contains("metal")||k.Contains("rough")||k.Contains("smooth")||k.Contains("gloss")||k.Contains("occlusion")||k=="_aomap"||k=="_detailmask")return "mask";if(k=="_maintex"||k.Contains("albedo")||k.Contains("basecolor")||k.Contains("emission")||k.Contains("artwork")||k=="_neutraltex")return "albedo";throw new Exception("Unclassified texture property: "+p);}
 static Policy Load(){var args=Environment.GetCommandLineArgs();int n=Array.IndexOf(args,"-vehiclePolicy");if(n<0||n+1>=args.Length)throw new Exception("Pass -vehiclePolicy <JSON path>");var p=JsonUtility.FromJson<Policy>(File.ReadAllText(args[n+1]));if(p.policyVersion!=1||p.albedoNormalMax!=2048||p.surfaceMaskMax!=256||p.vehicles.Length==0)throw new Exception("Invalid policy");if(!Application.isBatchMode||Application.unityVersion!="2022.3.62f2"||QualitySettings.activeColorSpace!=ColorSpace.Linear)throw new Exception("Require exact Unity2022.3.62f2 Linear batch editor");return p;}
 public static void Run(){var p=Load();Directory.CreateDirectory(p.output);string run=Path.Combine(p.output,"Runs",DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffZ"));Directory.CreateDirectory(run);var clock=Stopwatch.StartNew();var snapshots=new Dictionary<string,string>();var plans=new Dictionary<string,Plan>();var inventory=new List<string>{"vehicle\trenderer\tmaterial\tproperty\trole\ttexture\tbeforeWidth\tbeforeHeight\tbeforeFormat"};
 // Plan everything before importer mutations. Original image files never rewritten.
 foreach(var v in p.vehicles){ValidateDefinitions(p,v);foreach(string path in new[]{v.prefab,v.original}){if(!File.Exists(path))throw new Exception("Missing source "+path);snapshots[path]=Hash(path);}var root=AssetDatabase.LoadAssetAtPath<GameObject>(v.prefab);Contract(root,v);foreach(var r in root.GetComponentsInChildren<Renderer>(true))foreach(var m in r.sharedMaterials.Where(x=>x))foreach(string key in m.GetTexturePropertyNames()){var t=m.GetTexture(key) as Texture2D;if(!t)continue;string path=AssetDatabase.GetAssetPath(t);if(string.IsNullOrEmpty(path))continue;string role=Role(key);int cap=role=="mask"?p.surfaceMaskMax:p.albedoNormalMax;inventory.Add(v.name+"\t"+r.name+"\t"+m.name+"\t"+key+"\t"+role+"\t"+path+"\t"+t.width+"\t"+t.height+"\t"+t.format);if(plans.TryGetValue(path,out var existing)){if(existing.cap!=cap||existing.role!=role)throw new Exception("Conflicting shared texture roles: "+path);continue;}var i=AssetImporter.GetAtPath(path) as TextureImporter;if(!i)throw new Exception("Missing importer: "+path);i.GetSourceTextureWidthAndHeight(out int w,out int h);plans[path]=new Plan{path=path,role=role,cap=cap,sourceW=w,sourceH=h,imageHash=Hash(path),format=role=="normal"||key=="_MetallicGlossMap"||i.DoesSourceTextureHaveAlpha()?TextureImporterFormat.DXT5Crunched:TextureImporterFormat.DXT1Crunched};}}
 File.WriteAllLines(Path.Combine(run,"inventory-before.tsv"),inventory);var rows=new List<string>{"path\trole\tsourceWidth\tsourceHeight\tcap\twidth\theight\tformat\timageSHA256\tsettingsChanged"};int changed=0;
 foreach(var t in plans.Values){var i=(TextureImporter)AssetImporter.GetAtPath(t.path);var platform=i.GetPlatformTextureSettings("Standalone");bool change=i.maxTextureSize!=t.cap||i.textureCompression!=TextureImporterCompression.CompressedHQ||!i.crunchedCompression||i.compressionQuality!=p.crunchQuality||!platform.overridden||platform.maxTextureSize!=t.cap||platform.format!=t.format||!platform.crunchedCompression||platform.compressionQuality!=p.crunchQuality;
 if(change){File.Copy(t.path+".meta",Path.Combine(run,AssetDatabase.AssetPathToGUID(t.path)+".before.meta"));i.maxTextureSize=t.cap;i.textureCompression=TextureImporterCompression.CompressedHQ;i.crunchedCompression=true;i.compressionQuality=p.crunchQuality;platform.name="Standalone";platform.overridden=true;platform.maxTextureSize=t.cap;platform.format=t.format;platform.textureCompression=TextureImporterCompression.CompressedHQ;platform.crunchedCompression=true;platform.compressionQuality=p.crunchQuality;i.SetPlatformTextureSettings(platform);i.SaveAndReimport();changed++;}
 var a=AssetDatabase.LoadAssetAtPath<Texture2D>(t.path);if(a.width>Math.Min(t.cap,t.sourceW)||a.height>Math.Min(t.cap,t.sourceH))throw new Exception("Upscale or cap violation: "+t.path);if(!a.format.ToString().Contains("Crunched"))throw new Exception("Crunch not applied: "+t.path);if(Hash(t.path)!=t.imageHash)throw new Exception("Original image modified: "+t.path);rows.Add(t.path+"\t"+t.role+"\t"+t.sourceW+"\t"+t.sourceH+"\t"+t.cap+"\t"+a.width+"\t"+a.height+"\t"+a.format+"\t"+t.imageHash+"\t"+change);}
 foreach(var s in snapshots)if(Hash(s.Key)!=s.Value)throw new Exception("Source prefab modified: "+s.Key);AssetDatabase.SaveAssets();File.WriteAllLines(Path.Combine(run,"textures-verified.tsv"),rows);double importSeconds=clock.Elapsed.TotalSeconds;var builds=p.vehicles.Select(v=>new AssetBundleBuild{assetBundleName=v.bundle,assetNames=new[]{v.prefab}}).ToArray();string bundles=Path.Combine(p.output,"Bundles");Directory.CreateDirectory(bundles);if(!RebirthAssetBundlePackaging.BuildAssetBundles(bundles,builds,BuildAssetBundleOptions.ChunkBasedCompression,BuildTarget.StandaloneWindows64))throw new Exception("Build failed");double buildSeconds=clock.Elapsed.TotalSeconds-importSeconds;var proof=new List<string>();var hashes=new Dictionary<string,string>();
 foreach(var v in p.vehicles){string path=Path.Combine(bundles,v.bundle);Verify(path,v,proof);hashes[path]=Hash(path);proof.Add(v.name+" bytes="+new FileInfo(path).Length+" SHA256="+hashes[path]);}
 // Same invocation, unchanged inputs: cache/determinism smoke. No reimport or regeneration.
 var check=Stopwatch.StartNew();if(!RebirthAssetBundlePackaging.BuildAssetBundles(bundles,builds,BuildAssetBundleOptions.ChunkBasedCompression,BuildTarget.StandaloneWindows64))throw new Exception("Incremental check failed");foreach(var h in hashes)if(Hash(h.Key)!=h.Value)throw new Exception("Unchanged build hash differs: "+h.Key);
 proof.Add("PASS no-op rebuild same hashes; seconds="+check.Elapsed.TotalSeconds.ToString("F3"));proof.Add("Textures="+plans.Count+" changedImporters="+changed+" importSeconds="+importSeconds.ToString("F3")+" firstBuildSeconds="+buildSeconds.ToString("F3"));proof.Add("PASS source prefab/image preservation, texture caps/no-upscale/Crunch, native bundle contracts and texture references. Unity only; NOT installed or in-game qualified.");File.WriteAllLines(Path.Combine(run,"verified.txt"),proof);File.WriteAllText(Path.Combine(p.output,"latest-verified-run.txt"),run);UnityEngine.Debug.Log(string.Join("\n",proof));}
 public static void VerifyOnly(){var p=Load();var proof=new List<string>();foreach(var v in p.vehicles)Verify(Path.Combine(p.output,"Bundles",v.bundle),v,proof);File.WriteAllLines(Path.Combine(p.output,"verify-only.txt"),proof);}
 static void ValidateDefinitions(Policy p,Vehicle v){var items=new XmlDocument();items.Load(p.items);var item=items.SelectSingleNode("/configs/append/item[@name='"+v.name+"Placeable']");var durability=item?.SelectSingleNode("effect_group/passive_effect[@name='DegradationMax' and @operation='base_set']");if(durability==null||!int.TryParse(durability.Attributes["value"].Value,out int maximum)||maximum<=0)throw new Exception("Explicit native item durability required: "+v.name);var xml=new XmlDocument();xml.Load(p.definitions);var node=xml.SelectSingleNode("/configs/append/vehicle[@name='"+v.name+"']");if(node==null)throw new Exception("Matched vehicle definition missing");var seats=node.SelectNodes("property[starts-with(@class,'seat')]");if(seats.Count!=v.seats)throw new Exception("Seat XML count mismatch");for(int n=0;n<seats.Count;n++){string pose=seats[n].SelectSingleNode("property[@name='pose']").Attributes["value"].Value;if(pose!=(v.seats==1?"30":n==0?"40":"41"))throw new Exception("Native pose mismatch");}var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(v.prefab);foreach(XmlNode prop in node.SelectNodes(".//property[@name='transform' or @name='steerTransform' or @name='tireTransform' or @name='matT' or @name='modHideT']")){string target=prop.Attributes["value"].Value;if(!(prefab.transform.Find("GameObject")??prefab.transform).Find(target))throw new Exception("Missing XML target "+v.name+"/"+target);}}
 static void Contract(GameObject root,Vehicle v){if(!root)throw new Exception("Missing prefab "+v.name);var model=root.transform.Find("GameObject");if(!model)throw new Exception("Native EntityFactory requires a GameObject visual child: "+v.name);var physics=root.transform.Find("Physics");if(physics && physics.parent!=model.parent)throw new Exception("Native visual/physics transforms must be siblings");if(!physics||physics.tag!="Physics"||physics.gameObject.layer!=21||!physics.GetComponent<Rigidbody>())throw new Exception("Physics contract "+v.name);if(physics.GetComponentsInChildren<WheelCollider>(true).Length!=v.wheels)throw new Exception("Wheel count "+v.name);if(root.GetComponentsInChildren<MonoBehaviour>(true).Any(x=>x))throw new Exception("Runtime script in bundle");foreach(string path in new[]{"M/RearLights","M/RearLenses"})if(!model.Find(path))throw new Exception("Missing native target "+path);if(!root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Any(m=>m&&m.shader&&m.shader.name=="REBIRTH/StandardVehiclePaint"))throw new Exception("Paint contract "+v.name);}
 static void Verify(string path,Vehicle v,List<string> proof){if(!BuildPipeline.GetCRCForAssetBundle(path,out uint crc))throw new Exception("Missing CRC");var bundle=AssetBundle.LoadFromFile(path,crc);if(!bundle)throw new Exception("CRC reopen failed");try{var source=AssetDatabase.LoadAssetAtPath<GameObject>(v.prefab);var actual=bundle.LoadAsset<GameObject>(v.name);Contract(actual,v);var st=source.GetComponentsInChildren<Transform>(true);var at=actual.GetComponentsInChildren<Transform>(true);if(st.Length!=at.Length)throw new Exception("Hierarchy count mismatch");for(int n=0;n<st.Length;n++)if(st[n].name!=at[n].name||st[n].localPosition!=at[n].localPosition||Quaternion.Angle(st[n].localRotation,at[n].localRotation)>.001f||st[n].localScale!=at[n].localScale||st[n].gameObject.activeSelf!=at[n].gameObject.activeSelf)throw new Exception("Rig transform changed");var sr=source.GetComponentsInChildren<Renderer>(true);var ar=actual.GetComponentsInChildren<Renderer>(true);if(sr.Length!=ar.Length)throw new Exception("Renderer mismatch");for(int n=0;n<sr.Length;n++){var sm=sr[n].sharedMaterials;var am=ar[n].sharedMaterials;if(sm.Length!=am.Length)throw new Exception("Material slots changed");for(int m=0;m<sm.Length;m++){if(!sm[m])continue;if(sm[m].shader.name!=am[m].shader.name)throw new Exception("Shader changed");foreach(string key in sm[m].GetTexturePropertyNames()){if(!sm[m].HasProperty(key)){proof.Add("SKIP stale serialized slot unused by shader: "+sm[m].name+"/"+key);continue;}var e=sm[m].GetTexture(key) as Texture2D;if(!e)continue;var a=am[m].GetTexture(key) as Texture2D;if(!a||a.width!=e.width||a.height!=e.height||a.format!=e.format)throw new Exception("Texture mismatch "+v.name+" renderer="+sr[n].name+" material="+sm[m].name+" property="+key+" source="+AssetDatabase.GetAssetPath(e)+" "+e.width+"x"+e.height+" "+e.format+" actual="+(a?a.name+" "+a.width+"x"+a.height+" "+a.format:"NULL"));}}}proof.Add("PASS "+v.name+" CRC="+crc+" rig hierarchy/wheels/lights/shaders/textures preserved; seat XML contract requires separate configuration check");}finally{bundle.Unload(true);}}
}


